# Identify the most recent t-shirt order and list its t-shirt items
from datetime import datetime

def parse_dt(s):
    return datetime.fromisoformat(s.replace('Z','+00:00'))

# find most recent order among all_orders that contains a t-shirt item using same heuristic
all_orders_sorted = sorted(all_orders, key=lambda o: parse_dt(o['created_at']), reverse=True)

def is_tshirt_item(item, prod=None):
    ptype = (prod.get('product_type','') if prod else '')
    pname = (prod.get('name','') if prod else '')
    item_name = (item.get('product_name','') or '')
    if 't-shirt' in ptype.lower() or 'tshirt' in ptype.lower() or 'shirt' in ptype.lower() and 't' in ptype.lower():
        return True
    if 't-shirt' in item_name.lower() or 'tshirt' in item_name.lower():
        return True
    if 't-shirt' in pname.lower() or 'tshirt' in pname.lower():
        return True
    return False

most_recent_tshirt_order = None
for o in all_orders_sorted:
    tshirt_items = []
    for it in o.get('order_items', []):
        prod = apis.amazon.show_product(product_id=it['product_id'])
        if is_tshirt_item(it, prod):
            tshirt_items.append((it['product_id'], it.get('product_name'), prod.get('name'), prod.get('product_type')))
    if tshirt_items:
        most_recent_tshirt_order = (o, tshirt_items)
        break

print('most_recent_tshirt_order_created_at', most_recent_tshirt_order[0]['created_at'])
print('order_id', most_recent_tshirt_order[0]['order_id'])
print('tshirt_items_count', len(most_recent_tshirt_order[1]))
for t in most_recent_tshirt_order[1]:
    print(t)

